 55	static void blend_pixel(uint8_t *destination, uint32_t color, uint8_t coverage)
 56	{
 57	    uint32_t alpha = (((color & 255U) * (uint32_t)coverage) + 127U) / 255U;
 58	    uint32_t inverse = 255U - alpha;
 59	    uint32_t old_alpha = destination[3];
 60	    uint32_t out_alpha = alpha + (old_alpha * inverse + 127U) / 255U;
 61	    if (out_alpha == 0U) return;
 62	    for (size_t channel = 0U; channel < 3U; ++channel) {
 63	        uint32_t source = (color >> (24U - (uint32_t)(channel * 8U))) & 255U;
 64	        uint32_t numerator = source * alpha * 255U +
 65	            (uint32_t)destination[channel] * old_alpha * inverse;
 66	        destination[channel] = (uint8_t)((numerator + out_alpha * 127U) /
 67	            (out_alpha * 255U));
 68	    }
 69	    destination[3] = (uint8_t)out_alpha;
 70	}
