 72	static bool rounded_contains(double x, double y, double left, double top,
 73	    double right, double bottom, double radius)
 74	{
 75	    if (x < left || x >= right || y < top || y >= bottom) return false;
 76	    double cx = x < left + radius ? left + radius :
 77	        x >= right - radius ? right - radius : x;
 78	    double cy = y < top + radius ? top + radius :
 79	        y >= bottom - radius ? bottom - radius : y;
 80	    double dx = x - cx, dy = y - cy;
 81	    return dx * dx + dy * dy <= radius * radius;
 82	}
