 84	void ui_widget_paint_round(const ui_widget_canvas *canvas, ui_rect logical,
 85	    uint32_t radius_points, uint32_t fill, uint32_t edge, uint32_t edge_points)
 86	{
 87	    ui_rect rect = {0};
 88	    if (!scaled_rect(canvas, logical, &rect) || rect.x >= canvas->width ||
 89	        rect.y >= canvas->height) return;
 90	    uint32_t right_limit = rect.x + rect.width;
 91	    uint32_t bottom_limit = rect.y + rect.height;
 92	    if (right_limit < rect.x || right_limit > canvas->width) right_limit = canvas->width;
 93	    if (bottom_limit < rect.y || bottom_limit > canvas->height) bottom_limit = canvas->height;
 94	    double scale = (double)canvas->backing_scale * canvas->ui_scale;
 95	    double radius = (double)radius_points * scale;
 96	    if (radius > (double)rect.width / 2.0) radius = (double)rect.width / 2.0;
 97	    if (radius > (double)rect.height / 2.0) radius = (double)rect.height / 2.0;
 98	    double inset = (double)edge_points * scale;
 99	    double outer_left = rect.x, outer_top = rect.y;
100	    double outer_right = (double)rect.x + rect.width;
101	    double outer_bottom = (double)rect.y + rect.height;
102	    double inner_left = outer_left + inset, inner_top = outer_top + inset;
103	    double inner_right = outer_right - inset, inner_bottom = outer_bottom - inset;
104	    double inner_radius = radius > inset ? radius - inset : 0.0;
105	    for (uint32_t y = rect.y; y < bottom_limit; ++y) {
106	        for (uint32_t x = rect.x; x < right_limit; ++x) {
107	            unsigned fill_coverage = 0U, edge_coverage = 0U;
108	            for (unsigned sy = 0U; sy < UI_PAINT_SAMPLES; ++sy) {
109	                for (unsigned sx = 0U; sx < UI_PAINT_SAMPLES; ++sx) {
110	                    double px = (double)x + ((double)sx + 0.5) / UI_PAINT_SAMPLES;
111	                    double py = (double)y + ((double)sy + 0.5) / UI_PAINT_SAMPLES;
112	                    bool outer = rounded_contains(px, py, outer_left, outer_top,
113	                        outer_right, outer_bottom, radius);
114	                    if (!outer) continue;
115	                    bool inner = edge_points > 0U && inner_left < inner_right &&
116	                        inner_top < inner_bottom && rounded_contains(px, py,
117	                        inner_left, inner_top, inner_right, inner_bottom, inner_radius);
118	                    if (edge_points > 0U && !inner) edge_coverage++;
119	                    else if (fill != 0U) fill_coverage++;
120	                }
121	            }
122	            uint8_t *pixel = canvas->rgba + (size_t)y * canvas->stride + (size_t)x * 4U;
123	            if (fill_coverage > 0U && fill != 0U)
124	                blend_pixel(pixel, fill, (uint8_t)((fill_coverage * 255U + 8U) / 16U));
125	            if (edge_coverage > 0U && edge != 0U)
126	                blend_pixel(pixel, edge, (uint8_t)((edge_coverage * 255U + 8U) / 16U));
127	        }
128	    }
129	}
