179	static uint32_t blend_colors(uint32_t from, uint32_t to, uint16_t progress)
180	{
181	    double amount = (double)progress / 1000.0;
182	    uint32_t result = 0U;
183	    for (unsigned shift = 0U; shift < 32U; shift += 8U) {
184	        uint32_t left = (from >> shift) & 255U;
185	        uint32_t right = (to >> shift) & 255U;
186	        uint32_t channel = (uint32_t)llround((double)left * (1.0 - amount) +
187	            (double)right * amount);
188	        result |= channel << shift;
189	    }
190	    return result;
191	}
