282	bool ui_widget_number_parse(const char *text, size_t length, double *out_value)
283	{
284	    if (text == NULL || out_value == NULL || length == 0U || length > UI_WIDGET_EDIT_MAX_BYTES)
285	        return false;
286	    size_t start = 0U, end_offset = length;
287	    while (start < end_offset && (text[start] == ' ' || text[start] == '\t')) start++;
288	    while (end_offset > start && (text[end_offset - 1U] == ' ' || text[end_offset - 1U] == '\t')) end_offset--;
289	    if (start == end_offset) return false;
290	    size_t offset = start;
291	    if (text[offset] == '+' || text[offset] == '-') offset++;
292	    size_t integer_digits = 0U;
293	    while (offset < end_offset && text[offset] >= '0' && text[offset] <= '9') {
294	        integer_digits++; offset++;
295	    }
296	    size_t fraction_digits = 0U;
297	    if (offset < end_offset && text[offset] == '.') {
298	        offset++;
299	        while (offset < end_offset && text[offset] >= '0' && text[offset] <= '9') {
300	            fraction_digits++; offset++;
301	        }
302	    }
303	    if (integer_digits + fraction_digits == 0U) return false;
304	    if (offset < end_offset && (text[offset] == 'e' || text[offset] == 'E')) {
305	        offset++;
306	        if (offset < end_offset && (text[offset] == '+' || text[offset] == '-')) offset++;
307	        size_t exponent_digits = 0U;
308	        while (offset < end_offset && text[offset] >= '0' && text[offset] <= '9') {
309	            exponent_digits++; offset++;
310	        }
311	        if (exponent_digits == 0U) return false;
312	    }
313	    if (offset != end_offset || end_offset - start >= UI_WIDGET_EDIT_MAX_BYTES + 1U) return false;
314	    char bounded[UI_WIDGET_EDIT_MAX_BYTES + 1U];
315	    size_t bounded_length = end_offset - start;
316	    memcpy(bounded, text + start, bounded_length);
317	    bounded[bounded_length] = '\0';
318	    char *parse_end = NULL;
319	    errno = 0;
320	    double parsed = strtod(bounded, &parse_end);
321	    if (errno == ERANGE || parse_end != bounded + bounded_length || !isfinite(parsed)) return false;
322	    *out_value = parsed;
323	    return true;
324	}
