391	ui_widget_input_result ui_widget_number_field_key(ui_widget_number_field *field,
392	    uint32_t key, uint32_t modifiers)
393	{
394	    if (field == NULL) return UI_WIDGET_INPUT_INVALID;
395	    if (key == UI_KEY_UP || key == UI_KEY_DOWN) {
396	        double current = 0.0;
397	        if (!ui_widget_number_parse(field->edit.value, field->edit.length, &current) ||
398	            current < field->minimum || current > field->maximum) {
399	            field->edit.invalid = true;
400	            return UI_WIDGET_INPUT_INVALID;
401	        }
402	        double factor = (modifiers & UI_MOD_SHIFT) != 0U ? 10.0 :
403	            (modifiers & UI_MOD_OPTION) != 0U ? 0.1 : 1.0;
404	        double direction = key == UI_KEY_UP ? 1.0 : -1.0;
405	        if ((!field->edit.editing && !ui_widget_text_edit_begin(&field->edit)) ||
406	            !number_set_value(field, current + direction * field->step * factor))
407	            return UI_WIDGET_INPUT_INVALID;
408	        return UI_WIDGET_INPUT_CHANGED;
409	    }
410	    if (key == UI_KEY_RETURN) {
411	        double value = 0.0;
412	        if (!ui_widget_number_parse(field->edit.value, field->edit.length, &value) ||
413	            value < field->minimum || value > field->maximum) {
414	            field->edit.invalid = true;
415	            return UI_WIDGET_INPUT_INVALID;
416	        }
417	        field->value = value;
418	        field->edit.invalid = false;
419	        bool committed = ui_widget_text_edit_commit(&field->edit);
420	        if (committed) field->original = value;
421	        return committed ? UI_WIDGET_INPUT_COMMITTED : UI_WIDGET_INPUT_UNHANDLED;
422	    }
423	    if (key == UI_KEY_ESCAPE) {
424	        if (!ui_widget_text_edit_cancel(&field->edit)) return UI_WIDGET_INPUT_UNHANDLED;
425	        field->scrubbing = false;
426	        if (!ui_widget_number_parse(field->edit.value, field->edit.length, &field->value))
427	            return UI_WIDGET_INPUT_INVALID;
428	        return UI_WIDGET_INPUT_CANCELLED;
429	    }
430	    ui_widget_input_result result = ui_widget_text_edit_key(&field->edit, key, modifiers);
431	    if (result == UI_WIDGET_INPUT_CHANGED) {
432	        double value = 0.0;
