440	ui_widget_input_result ui_widget_number_field_pointer(ui_widget_number_field *field,
441	    ui_widget_pointer_event event, int32_t x, uint32_t modifiers)
442	{
443	    if (field == NULL || event > UI_WIDGET_POINTER_CANCEL) return UI_WIDGET_INPUT_INVALID;
444	    if (event == UI_WIDGET_POINTER_DOWN) {
445	        if (!ui_widget_text_edit_begin(&field->edit)) return UI_WIDGET_INPUT_INVALID;
446	        field->scrub_origin_x = x;
447	        field->scrub_origin_value = field->value;
448	        field->scrubbing = true;
449	        return UI_WIDGET_INPUT_CHANGED;
450	    }
451	    if (event == UI_WIDGET_POINTER_ENTER || event == UI_WIDGET_POINTER_LEAVE)
452	        return UI_WIDGET_INPUT_UNHANDLED;
453	    if (event == UI_WIDGET_POINTER_MOVE && !field->scrubbing)
454	        return UI_WIDGET_INPUT_UNHANDLED;
455	    if (!field->scrubbing) return UI_WIDGET_INPUT_UNHANDLED;
456	    if (event == UI_WIDGET_POINTER_CANCEL || event == UI_WIDGET_POINTER_UP_OUTSIDE) {
457	        field->scrubbing = false;
458	        if (!ui_widget_text_edit_cancel(&field->edit)) return UI_WIDGET_INPUT_INVALID;
459	        field->value = field->scrub_origin_value;
460	        return UI_WIDGET_INPUT_CANCELLED;
461	    }
462	    if (event == UI_WIDGET_POINTER_UP_INSIDE) {
463	        field->scrubbing = false;
464	        field->original = field->value;
465	        return ui_widget_text_edit_commit(&field->edit) ? UI_WIDGET_INPUT_COMMITTED :
466	            UI_WIDGET_INPUT_UNHANDLED;
467	    }
468	    double multiplier = (modifiers & UI_MOD_SHIFT) != 0U ? 10.0 :
469	        (modifiers & UI_MOD_OPTION) != 0U ? 0.1 : 1.0;
470	    double delta = ((double)x - (double)field->scrub_origin_x) * 0.25 * multiplier;
471	    return number_set_value(field, field->scrub_origin_value + delta) ?
472	        UI_WIDGET_INPUT_CHANGED : UI_WIDGET_INPUT_INVALID;
473	}
