475	static int hex_digit(char character)
476	{
477	    if (character >= '0' && character <= '9') return character - '0';
478	    if (character >= 'a' && character <= 'f') return character - 'a' + 10;
479	    if (character >= 'A' && character <= 'F') return character - 'A' + 10;
480	    return -1;
481	}
482	
483	bool ui_widget_hex_parse(const char *text, size_t length, uint32_t *out_rgba)
484	{
485	    if (text == NULL || out_rgba == NULL) return false;
486	    size_t start = length > 0U && text[0] == '#' ? 1U : 0U;
487	    size_t digits = length - start;
488	    if (digits != 3U && digits != 4U && digits != 6U && digits != 8U) return false;
489	    uint8_t channels[4] = {0U, 0U, 0U, 255U};
490	    if (digits <= 4U) {
491	        for (size_t channel = 0U; channel < digits; ++channel) {
492	            int value = hex_digit(text[start + channel]);
493	            if (value < 0) return false;
494	            channels[channel] = (uint8_t)(value * 17);
495	        }
496	    } else {
497	        size_t count = digits / 2U;
498	        for (size_t channel = 0U; channel < count; ++channel) {
499	            int high = hex_digit(text[start + channel * 2U]);
500	            int low = hex_digit(text[start + channel * 2U + 1U]);
501	            if (high < 0 || low < 0) return false;
502	            channels[channel] = (uint8_t)((high << 4) | low);
503	        }
504	    }
505	    *out_rgba = ((uint32_t)channels[0] << 24U) | ((uint32_t)channels[1] << 16U) |
506	        ((uint32_t)channels[2] << 8U) | channels[3];
507	    return true;
508	}
