510	bool ui_widget_hex_format(uint32_t rgba, char *buffer, size_t capacity,
511	                          size_t *out_length)
512	{
513	    if (buffer == NULL) return false;
514	    unsigned red = (rgba >> 24U) & 255U, green = (rgba >> 16U) & 255U;
515	    unsigned blue = (rgba >> 8U) & 255U, alpha = rgba & 255U;
516	    int written = alpha == 255U ? snprintf(buffer, capacity, "#%02X%02X%02X", red, green, blue) :
517	        snprintf(buffer, capacity, "#%02X%02X%02X%02X", red, green, blue, alpha);
518	    if (written < 0 || (size_t)written >= capacity) return false;
519	    if (out_length != NULL) *out_length = (size_t)written;
520	    return true;
521	}
