613	static double slider_at(int32_t x, int32_t track_x, uint32_t track_width,
614	                        double minimum, double maximum, double step)
615	{
616	    double position = (double)x - (double)track_x;
617	    if (position < 0.0) position = 0.0;
618	    if (position > (double)track_width) position = (double)track_width;
619	    double ratio = track_width == 0U ? 0.0 : position / (double)track_width;
620	    double value = minimum + ratio * (maximum - minimum);
621	    if (step > 0.0) value = minimum + round((value - minimum) / step) * step;
622	    if (value < minimum) value = minimum;
623	    if (value > maximum) value = maximum;
624	    return value;
625	}
