649	        option_count > UI_WIDGET_MAX_OPTIONS || selected_index >= option_count) return false;
650	    ui_widget_dropdown fresh = {0};
651	    if (!copy_label(fresh.semantic_label, sizeof(fresh.semantic_label), semantic_label,
652	            label_length, true)) return false;
653	    for (size_t index = 0U; index < option_count; ++index) {
654	        if (!copy_label(fresh.options[index], sizeof(fresh.options[index]),
655	                options[index].text, options[index].length, true)) return false;
656	        fresh.option_lengths[index] = (uint8_t)options[index].length;
657	    }
658	    fresh.semantic_label_length = label_length;
