665	ui_widget_input_result ui_widget_dropdown_key(ui_widget_dropdown *dropdown,
666	    uint32_t key, uint32_t modifiers)
667	{
668	    (void)modifiers;
669	    if (dropdown == NULL || dropdown->option_count == 0U) return UI_WIDGET_INPUT_INVALID;
670	    if (!dropdown->expanded) {
671	        if (key != UI_KEY_RETURN && key != UI_KEY_SPACE && key != UI_KEY_DOWN &&
672	            key != UI_KEY_UP) return UI_WIDGET_INPUT_UNHANDLED;
673	        dropdown->expanded = true;
674	        dropdown->active_index = dropdown->selected_index;
675	        return UI_WIDGET_INPUT_CHANGED;
676	    }
677	    if (key == UI_KEY_ESCAPE) {
678	        dropdown->expanded = false; dropdown->active_index = dropdown->selected_index;
679	        return UI_WIDGET_INPUT_CANCELLED;
680	    }
681	    if (key == UI_KEY_RETURN || key == UI_KEY_SPACE) {
682	        dropdown->selected_index = dropdown->active_index;
683	        dropdown->expanded = false;
684	        return UI_WIDGET_INPUT_COMMITTED;
685	    }
686	    if (key == UI_KEY_UP || key == UI_KEY_LEFT) {
687	        dropdown->active_index = dropdown->active_index == 0U ? dropdown->option_count - 1U :
688	            dropdown->active_index - 1U;
689	        return UI_WIDGET_INPUT_CHANGED;
690	    }
691	    if (key == UI_KEY_DOWN || key == UI_KEY_RIGHT) {
692	        dropdown->active_index = (dropdown->active_index + 1U) % dropdown->option_count;
693	        return UI_WIDGET_INPUT_CHANGED;
694	    }
695	    return UI_WIDGET_INPUT_UNHANDLED;
696	}

