 10	static size_t utf8_next(const char *text, size_t length, size_t offset)
 11	{
 12	    if (text == NULL || offset >= length) return length;
 13	    uint8_t first = (uint8_t)text[offset];
 14	    size_t step = first < 0x80U ? 1U : first < 0xe0U ? 2U :
 15	        first < 0xf0U ? 3U : 4U;
 16	    return step > length - offset ? length : offset + step;
 17	}
 18	
 19	static size_t utf8_count(const char *text, size_t length)
 20	{
 21	    size_t count = 0U;
 22	    for (size_t offset = 0U; offset < length; offset = utf8_next(text, length, offset))
 23	        ++count;
 24	    return count;
 25	}
 26	
 27	static size_t utf8_offset_after(const char *text, size_t length, size_t count)
 28	{
 29	    size_t offset = 0U;
 30	    while (offset < length && count > 0U) {
 31	        offset = utf8_next(text, length, offset);
 32	        --count;
 33	    }
 34	    return offset;
 35	}
