 79	static size_t trailing_ellipsis(const char *text, size_t length,
 80	    size_t maximum_characters, char output[UI_TEXT_MAX_BYTES])
 81	{
 82	    static const char ellipsis[] = "\xe2\x80\xa6";
 83	    size_t characters = utf8_count(text, length);
 84	    if (characters <= maximum_characters && length < UI_TEXT_MAX_BYTES) {
 85	        if (length > 0U) memcpy(output, text, length);
 86	        output[length] = '\0';
 87	        return length;
 88	    }
 89	    if (maximum_characters == 0U) {
 90	        output[0] = '\0';
 91	        return 0U;
 92	    }
 93	    size_t prefix_characters = maximum_characters - 1U;
 94	    size_t prefix_bytes = utf8_offset_after(text, length, prefix_characters);
 95	    while (prefix_bytes + sizeof(ellipsis) - 1U >= UI_TEXT_MAX_BYTES &&
 96	           prefix_characters > 0U) {
 97	        --prefix_characters;
 98	        prefix_bytes = utf8_offset_after(text, length, prefix_characters);
 99	    }
100	    if (prefix_bytes > 0U) memcpy(output, text, prefix_bytes);
101	    memcpy(output + prefix_bytes, ellipsis, sizeof(ellipsis) - 1U);
102	    size_t used = prefix_bytes + sizeof(ellipsis) - 1U;
103	    output[used] = '\0';
104	    return used;
105	}
