 37	static size_t middle_ellipsis(const char *text, size_t length,
 38	    size_t maximum_characters, char output[UI_TEXT_MAX_BYTES])
 39	{
 40	    static const char ellipsis[] = "\xe2\x80\xa6";
 41	    size_t characters = utf8_count(text, length);
 42	    if (characters <= maximum_characters && length < UI_TEXT_MAX_BYTES) {
 43	        if (length > 0U) memcpy(output, text, length);
 44	        output[length] = '\0';
 45	        return length;
 46	    }
 47	    if (maximum_characters == 0U) {
 48	        output[0] = '\0';
 49	        return 0U;
 50	    }
 51	    size_t left_characters = maximum_characters / 2U;
 52	    size_t right_characters = maximum_characters - left_characters - 1U;
 53	    size_t left_bytes = utf8_offset_after(text, length, left_characters);
 54	    size_t right_start = utf8_offset_after(text, length, characters - right_characters);
 55	    size_t right_bytes = length - right_start;
 56	    while (left_bytes + sizeof(ellipsis) - 1U >= UI_TEXT_MAX_BYTES &&
 57	           left_characters > 0U) {
 58	        --left_characters;
 59	        left_bytes = utf8_offset_after(text, length, left_characters);
 60	    }
 61	    while (left_bytes + sizeof(ellipsis) - 1U + right_bytes >= UI_TEXT_MAX_BYTES &&
 62	           right_characters > 0U) {
 63	        --right_characters;
 64	        right_start = utf8_offset_after(text, length, characters - right_characters);
 65	        right_bytes = length - right_start;
 66	    }
 67	    if (left_bytes > 0U) memcpy(output, text, left_bytes);
 68	    size_t used = left_bytes;
 69	    memcpy(output + used, ellipsis, sizeof(ellipsis) - 1U);
 70	    used += sizeof(ellipsis) - 1U;
 71	    if (right_bytes > 0U) {
 72	        memcpy(output + used, text + length - right_bytes, right_bytes);
 73	        used += right_bytes;
 74	    }
 75	    output[used] = '\0';
 76	    return used;
 77	}
