107	bool ui_widget_paint_tree_row(const ui_widget_canvas *canvas, const ui_widget_draw_spec *spec)
108	{
109	    uint32_t bg = spec->state == UI_CONTROL_SELECTED ? canvas->tokens.selection_fill :
110	        spec->state == UI_CONTROL_HOVER || spec->state == UI_CONTROL_PRESSED ?
111	            canvas->tokens.panel_hover : 0U;
112	    if (spec->has_transition) {
113	        double amount = (double)spec->transition_progress_permille / 1000.0;
114	        bg = 0U;
115	        for (unsigned shift = 0U; shift < 32U; shift += 8U) {
116	            uint32_t left = (spec->transition_from_color >> shift) & 255U;
117	            uint32_t right = (spec->transition_to_color >> shift) & 255U;
118	            uint32_t channel = (uint32_t)llround((double)left * (1.0 - amount) +
119	                (double)right * amount);
120	            bg |= channel << shift;
121	        }
122	    }
123	    if (bg != 0U) ui_widget_paint_round(canvas, spec->bounds, 4U, bg, 0U, 0U);
124	    double selected_amount = spec->state == UI_CONTROL_SELECTED ? 1.0 : 0.0;
125	    if (spec->has_transition) {
126	        double progress = (double)spec->transition_progress_permille / 1000.0;
127	        selected_amount = spec->transition_from == UI_CONTROL_SELECTED ? 1.0 - progress :
128	            spec->transition_to == UI_CONTROL_SELECTED ? progress : 0.0;
129	    }
130	    if (selected_amount > 0.0)
131	        ui_widget_paint_round(canvas, (ui_rect){spec->bounds.x, spec->bounds.y + 4U, 2U,
132	            spec->bounds.height > 8U ? spec->bounds.height - 8U : 1U},
133	            1U, (canvas->tokens.accent & UINT32_C(0xffffff00)) |
134	                (uint32_t)llround(selected_amount * 255.0), 0U, 0U);
135	    uint32_t guide_x = spec->bounds.x + 12U;
136	    for (uint32_t depth = 0U; depth < spec->indent && depth < 6U; ++depth) {
137	        ui_rect guide = {guide_x + depth * UI_TREE_ROW_INDENT_POINTS,
138	            spec->bounds.y, 1U, spec->bounds.height};
139	        ui_widget_paint_rect(canvas, guide, canvas->tokens.separator);
140	    }
141	    uint32_t start = spec->bounds.x + 4U +
142	        (uint32_t)spec->indent * UI_TREE_ROW_INDENT_POINTS;
143	    if (spec->has_children) {
144	        ui_icon_kind disclosure = spec->expanded ? UI_ICON_CHEVRON_DOWN : UI_ICON_CHEVRON_RIGHT;
145	        bool drawn = spec->visible ? ui_widget_paint_icon(canvas, disclosure,
146	                (ui_rect){start, spec->bounds.y + 5U, 16U, 16U}, spec->state) :
147	            ui_widget_paint_icon_color(canvas, disclosure,
148	                (ui_rect){start, spec->bounds.y + 5U, 16U, 16U},
149	                canvas->tokens.text_secondary);
150	        if (!drawn) return false;
151	    }
152	    start += 18U;
153	    if (spec->icon != UI_ICON_NONE) {
154	        bool drawn = spec->visible ? ui_widget_paint_icon(canvas, spec->icon,
155	                (ui_rect){start, spec->bounds.y + 5U, 16U, 16U}, spec->state) :
156	            ui_widget_paint_icon_color(canvas, spec->icon,
157	                (ui_rect){start, spec->bounds.y + 5U, 16U, 16U},
158	                canvas->tokens.text_secondary);
159	        if (!drawn) return false;
160	    }
161	    start += 20U;
162	    uint32_t trailing_width = spec->show_row_actions ? 40U : 8U;
163	    uint32_t right = spec->bounds.x + spec->bounds.width;
164	    uint32_t text_right = right > trailing_width ? right - trailing_width : start;
165	    const char *primary = spec->label;
166	    size_t primary_length = spec->label_length;
167	    const char *identifier = NULL;
168	    size_t identifier_length = 0U;
169	    for (size_t index = 0U; index + 1U < spec->label_length; ++index) {
170	        if (spec->label[index] != ' ' || spec->label[index + 1U] != '#') continue;
171	        primary_length = index;
172	        identifier = spec->label + index + 1U;
173	        identifier_length = spec->label_length - index - 1U;
174	        break;
175	    }
176	    uint32_t available = text_right > start ? text_right - start : 0U;
177	    size_t primary_characters = utf8_count(primary, primary_length);
178	    uint64_t primary_natural_width = (uint64_t)primary_characters * 7U;
179	    uint32_t identifier_width = 0U;
180	    if (identifier != NULL && primary_natural_width + 32U < available) {
181	        uint32_t remaining = available - (uint32_t)primary_natural_width - 8U;
182	        identifier_width = remaining > 64U ? 64U : remaining;
183	        if (identifier_width < 21U) identifier_width = 0U;
184	    }
185	    uint32_t primary_width = identifier_width > 0U ?
186	        available - identifier_width - 4U : available;
187	    ui_rect primary_bounds = {start, spec->bounds.y, primary_width, spec->bounds.height};
188	    uint32_t primary_color = spec->visible ? ui_widget_paint_state_foreground(canvas, spec->state) :
189	        canvas->tokens.text_secondary;
190	    char primary_display[UI_TEXT_MAX_BYTES] = {0};
191	    size_t primary_display_length = middle_ellipsis(primary, primary_length,
192	        primary_width / 7U, primary_display);
193	    if (!ui_widget_paint_text(canvas, primary_display, primary_display_length, primary_bounds,
194	            primary_color, UI_FONT_SYSTEM, UI_FONT_REGULAR, UI_POINT_TEXT)) return false;
195	    if (identifier_width > 0U) {
196	        ui_rect id_bounds = {text_right - identifier_width, spec->bounds.y,
197	            identifier_width, spec->bounds.height};
198	        uint32_t id_color = spec->visible ? canvas->tokens.text_tertiary :
199	            canvas->tokens.text_secondary;
200	        char identifier_display[UI_TEXT_MAX_BYTES] = {0};
201	        size_t identifier_display_length = trailing_ellipsis(identifier, identifier_length,
202	            identifier_width / 7U, identifier_display);
203	        if (!ui_widget_paint_text(canvas, identifier_display, identifier_display_length, id_bounds,
204	                id_color, UI_FONT_SYSTEM, UI_FONT_REGULAR, 12U)) return false;
205	    }
206	    if (!spec->show_row_actions) return true;
207	    uint32_t trail_x = spec->bounds.x + (spec->bounds.width > 34U ? spec->bounds.width - 34U : 0U);
208	    ui_control_state action_state = spec->state == UI_CONTROL_SELECTED ?
209	        UI_CONTROL_SELECTED : UI_CONTROL_HOVER;
210	    if (!ui_widget_paint_icon(canvas, spec->visible ? UI_ICON_EYE : UI_ICON_EYE_OFF,
211	            (ui_rect){trail_x, spec->bounds.y + 4U, 16U, 16U}, action_state)) return false;
212	    return ui_widget_paint_icon(canvas, spec->locked ? UI_ICON_LOCK : UI_ICON_UNLOCK,
213	        (ui_rect){trail_x + 16U, spec->bounds.y + 4U, 16U, 16U}, action_state);
214	}
