 15	static bool utf8_valid(const char *text, size_t length)
 16	{
 17	    if (length > 0U && text == NULL) return false;
 18	    for (size_t index = 0U; index < length;) {
 19	        uint8_t first = (uint8_t)text[index];
 20	        size_t extra = 0U;
 21	        uint8_t minimum = 0x80U, maximum = 0xbfU;
 22	        if (first <= 0x7fU) { index++; continue; }
 23	        if (first >= 0xc2U && first <= 0xdfU) extra = 1U;
 24	        else if (first == 0xe0U) { extra = 2U; minimum = 0xa0U; }
 25	        else if (first >= 0xe1U && first <= 0xecU) extra = 2U;
 26	        else if (first == 0xedU) { extra = 2U; maximum = 0x9fU; }
 27	        else if (first >= 0xeeU && first <= 0xefU) extra = 2U;
 28	        else if (first == 0xf0U) { extra = 3U; minimum = 0x90U; }
 29	        else if (first >= 0xf1U && first <= 0xf3U) extra = 3U;
 30	        else if (first == 0xf4U) { extra = 3U; maximum = 0x8fU; }
 31	        else return false;
 32	        if (extra > length - index - 1U) return false;
 33	        uint8_t second = (uint8_t)text[index + 1U];
 34	        if (second < minimum || second > maximum) return false;
 35	        for (size_t offset = 2U; offset <= extra; ++offset) {
 36	            uint8_t byte = (uint8_t)text[index + offset];
 37	            if (byte < 0x80U || byte > 0xbfU) return false;
 38	        }
 39	        index += extra + 1U;
 40	    }
 41	    return true;
 42	}
