 44	static bool copy_label(char *destination, size_t capacity, const char *source,
 45	                       size_t length, bool require_nonempty)
 46	{
 47	    if (source == NULL || capacity == 0U || length >= capacity ||
 48	        (require_nonempty && length == 0U) || !utf8_valid(source, length)) return false;
 49	    if (length > 0U) memcpy(destination, source, length);
 50	    destination[length] = '\0';
 51	    return true;
 52	}
