 54	static bool utf8_boundary(const char *text, size_t length, size_t offset)
 55	{
 56	    return offset <= length &&
 57	        (offset == length || (((uint8_t)text[offset] & 0xc0U) != 0x80U));
 58	}
 59	
 60	static size_t previous_codepoint(const char *text, size_t offset)
 61	{
 62	    if (offset == 0U) return 0U;
 63	    offset--;
 64	    while (offset > 0U && (((uint8_t)text[offset] & 0xc0U) == 0x80U)) offset--;
 65	    return offset;
 66	}
 67	
 68	static size_t next_codepoint(const char *text, size_t length, size_t offset)
 69	{
 70	    if (offset >= length) return length;
 71	    offset++;
 72	    while (offset < length && (((uint8_t)text[offset] & 0xc0U) == 0x80U)) offset++;
 73	    return offset;
 74	}
