 76	static void selection_range(const ui_widget_text_edit *edit, size_t *start,
 77	                            size_t *end)
 78	{
 79	    *start = edit->cursor < edit->anchor ? edit->cursor : edit->anchor;
 80	    *end = edit->cursor > edit->anchor ? edit->cursor : edit->anchor;
 81	}
