 83	static bool encode_codepoint(uint32_t codepoint, char encoded[4], size_t *length)
 84	{
 85	    if (codepoint <= 0x7fU) { encoded[0] = (char)codepoint; *length = 1U; }
 86	    else if (codepoint <= 0x7ffU) {
 87	        encoded[0] = (char)(0xc0U | (codepoint >> 6U));
 88	        encoded[1] = (char)(0x80U | (codepoint & 0x3fU)); *length = 2U;
 89	    } else if (codepoint >= 0xd800U && codepoint <= 0xdfffU) return false;
 90	    else if (codepoint <= 0xffffU) {
 91	        encoded[0] = (char)(0xe0U | (codepoint >> 12U));
 92	        encoded[1] = (char)(0x80U | ((codepoint >> 6U) & 0x3fU));
 93	        encoded[2] = (char)(0x80U | (codepoint & 0x3fU)); *length = 3U;
 94	    } else if (codepoint <= 0x10ffffU) {
 95	        encoded[0] = (char)(0xf0U | (codepoint >> 18U));
 96	        encoded[1] = (char)(0x80U | ((codepoint >> 12U) & 0x3fU));
 97	        encoded[2] = (char)(0x80U | ((codepoint >> 6U) & 0x3fU));
 98	        encoded[3] = (char)(0x80U | (codepoint & 0x3fU)); *length = 4U;
 99	    } else return false;
100	    return codepoint >= 0x20U && codepoint != 0x7fU;
101	}
