113	bool ui_widget_pointer_transition(ui_widget_pointer_state *state,
114	                                  ui_widget_pointer_event event)
115	{
116	    if (state == NULL || event < UI_WIDGET_POINTER_ENTER ||
117	        event > UI_WIDGET_POINTER_CANCEL) return false;
118	    if (!state->enabled) {
119	        state->hovered = false;
120	        state->pressed = false;
121	        return false;
122	    }
123	    switch (event) {
124	        case UI_WIDGET_POINTER_ENTER: state->hovered = true; break;
125	        case UI_WIDGET_POINTER_LEAVE:
126	            state->hovered = false;
127	            if (!state->pressed) state->focused = false;
128	            break;
129	        case UI_WIDGET_POINTER_MOVE: break;
130	        case UI_WIDGET_POINTER_DOWN:
131	            if (!state->hovered) return false;
132	            state->pressed = true;
133	            state->focused = true;
134	            break;
135	        case UI_WIDGET_POINTER_UP_INSIDE: {
136	            bool activated = state->pressed && state->hovered;
137	            state->pressed = false;
138	            return activated;
139	        }
140	        case UI_WIDGET_POINTER_UP_OUTSIDE:
141	        case UI_WIDGET_POINTER_CANCEL: state->pressed = false; break;
142	    }
143	    return false;
144	}
