198	static bool edit_insert(ui_widget_text_edit *edit, const char *bytes, size_t length)
199	{
200	    size_t start = 0U, end = 0U;
201	    selection_range(edit, &start, &end);
202	    size_t base = edit->length - (end - start);
203	    if (length > UI_WIDGET_EDIT_MAX_BYTES - base) return false;
204	    memmove(edit->value + start + length, edit->value + end, edit->length - end);
205	    memcpy(edit->value + start, bytes, length);
206	    edit->length = base + length;
207	    edit->value[edit->length] = '\0';
208	    edit->cursor = start + length;
209	    edit->anchor = edit->cursor;
210	    edit->invalid = false;
211	    return true;
212	}
