214	static void edit_delete_selection(ui_widget_text_edit *edit, size_t start, size_t end)
215	{
216	    memmove(edit->value + start, edit->value + end, edit->length - end);
217	    edit->length -= end - start;
218	    edit->value[edit->length] = '\0';
219	    edit->cursor = start;
220	    edit->anchor = start;
221	}
222	
223	ui_widget_input_result ui_widget_text_edit_key(ui_widget_text_edit *edit,
224	    uint32_t key, uint32_t modifiers)
225	{
226	    if (edit == NULL) return UI_WIDGET_INPUT_INVALID;
227	    if (key == UI_KEY_ESCAPE) {
228	        return ui_widget_text_edit_cancel(edit) ? UI_WIDGET_INPUT_CANCELLED :
229	            UI_WIDGET_INPUT_UNHANDLED;
230	    }
231	    if (key == UI_KEY_RETURN) {
232	        if (edit->invalid) return UI_WIDGET_INPUT_INVALID;
233	        return ui_widget_text_edit_commit(edit) ? UI_WIDGET_INPUT_COMMITTED :
234	            UI_WIDGET_INPUT_UNHANDLED;
235	    }
236	    if ((modifiers & UI_MOD_COMMAND) != 0U) return UI_WIDGET_INPUT_UNHANDLED;
237	    if (!edit->editing && !ui_widget_text_edit_begin(edit)) return UI_WIDGET_INPUT_INVALID;
238	    bool extend = (modifiers & UI_MOD_SHIFT) != 0U;
239	    if (key == UI_KEY_LEFT || key == UI_KEY_RIGHT || key == UI_KEY_HOME || key == UI_KEY_END) {
240	        size_t destination = edit->cursor;
241	        if (key == UI_KEY_LEFT) destination = previous_codepoint(edit->value, destination);
242	        else if (key == UI_KEY_RIGHT) destination = next_codepoint(edit->value, edit->length, destination);
243	        else if (key == UI_KEY_HOME) destination = 0U;
244	        else destination = edit->length;
245	        edit->cursor = destination;
246	        if (!extend) edit->anchor = destination;
247	        return UI_WIDGET_INPUT_CHANGED;
248	    }
249	    if (key == UI_KEY_BACKSPACE || key == UI_KEY_DELETE) {
250	        size_t start = 0U, end = 0U;
251	        selection_range(edit, &start, &end);
252	        if (start == end) {
253	            if (key == UI_KEY_BACKSPACE) start = previous_codepoint(edit->value, start);
254	            else end = next_codepoint(edit->value, edit->length, end);
255	        }
256	        if (start == end) return UI_WIDGET_INPUT_CHANGED;
257	        edit_delete_selection(edit, start, end);
258	        return UI_WIDGET_INPUT_CHANGED;
259	    }
260	    if (key < 0x20U || key >= 0x110000U) return UI_WIDGET_INPUT_UNHANDLED;
261	    char encoded[4];
262	    size_t encoded_length = 0U;
263	    if (!encode_codepoint(key, encoded, &encoded_length) ||
264	        !edit_insert(edit, encoded, encoded_length)) {
265	        edit->invalid = true;
266	        return UI_WIDGET_INPUT_INVALID;
267	    }
268	    return UI_WIDGET_INPUT_CHANGED;
269	}
