271	bool ui_widget_text_edit_pointer(ui_widget_text_edit *edit, size_t byte_offset,
272	                                 bool extend_selection)
273	{
274	    if (edit == NULL || byte_offset > edit->length ||
275	        !utf8_boundary(edit->value, edit->length, byte_offset)) return false;
276	    if (!edit->editing && !ui_widget_text_edit_begin(edit)) return false;
277	    edit->cursor = byte_offset;
278	    if (!extend_selection) edit->anchor = byte_offset;
279	    return true;
280	}

