11	static uint32_t random_next(uint32_t *state)
12	{
13	    uint32_t value = *state;
14	    value ^= value << 13U;
15	    value ^= value >> 17U;
16	    value ^= value << 5U;
17	    *state = value == 0U ? UINT32_C(0x9e3779b9) : value;
18	    return *state;
19	}
