21	static bool parse_argument(const char *text, uint32_t *out_value)
22	{
23	    if (text == NULL || out_value == NULL || text[0] == '\0') return false;
24	    char *end = NULL;
25	    unsigned long value = strtoul(text, &end, 10);
26	    if (end == text || *end != '\0' || value == 0UL || value > UINT32_MAX) return false;
27	    *out_value = (uint32_t)value;
28	    return true;
29	}
