31	int main(int argc, char **argv)
32	{
33	    uint32_t cases = 200000U;
34	    uint32_t seed = UINT32_C(20261010);
35	    if ((argc > 3) || (argc > 1 && !parse_argument(argv[1], &cases)) ||
36	        (argc > 2 && !parse_argument(argv[2], &seed))) {
37	        (void)fprintf(stderr, "usage: ui_widget_fuzz [cases [seed]]\n");
38	        return 2;
39	    }
40	    uint32_t state = seed;
41	    uint8_t input[MAX_FUZZ_BYTES];
42	    char encoded[UI_WIDGET_EDIT_MAX_BYTES + 1U];
43	    uint64_t number_valid = 0U, hex_valid = 0U;
44	    for (uint32_t iteration = 0U; iteration < cases; ++iteration) {
45	        size_t length = (size_t)(random_next(&state) % (MAX_FUZZ_BYTES + 1U));
46	        for (size_t index = 0U; index < length; ++index)
47	            input[index] = (uint8_t)(random_next(&state) & 0xffU);
48	        if ((iteration & 15U) == 0U) {
49	            static const char *number_samples[] = {"0", "-1.25", "+.5", "6e-4", " 14.0 "};
50	            const char *number = number_samples[(iteration >> 4U) % 5U];
51	            length = strlen(number);
52	            memcpy(input, number, length);
53	        }
54	        double number = 0.0;
55	        if (ui_widget_number_parse((const char *)input, length, &number)) {
56	            number_valid++;
57	            if (!isfinite(number)) return 3;
58	            size_t output_length = 0U;
59	            if (!ui_widget_number_format(number, encoded, sizeof(encoded), &output_length)) return 4;
60	            double round_trip = 0.0;
61	            if (!ui_widget_number_parse(encoded, output_length, &round_trip) ||
62	                fabs(number - round_trip) > fmax(1.0, fabs(number)) * 1e-14) return 5;
63	        }
64	        uint32_t rgba = 0U;
65	        if (ui_widget_hex_parse((const char *)input, length, &rgba)) {
66	            hex_valid++;
67	            size_t output_length = 0U;
68	            if (!ui_widget_hex_format(rgba, encoded, sizeof(encoded), &output_length)) return 6;
69	            uint32_t round_trip = 0U;
70	            if (!ui_widget_hex_parse(encoded, output_length, &round_trip) || round_trip != rgba)
71	                return 7;
72	        }
73	        if ((iteration & 15U) == 0U) {
74	            static const char *hex_samples[] = {"#000", "#4f7c", "#12aBef", "#12345678"};
75	            const char *hex = hex_samples[(iteration >> 4U) % 4U];
76	            size_t hex_length = strlen(hex);
77	            if (ui_widget_hex_parse(hex, hex_length, &rgba)) hex_valid++;
78	        }
79	    }
80	    (void)printf("{\"cases\":%u,\"seed\":%u,\"number_valid\":%llu,\"hex_valid\":%llu}\n",
81	        cases, seed, (unsigned long long)number_valid, (unsigned long long)hex_valid);
82	    return 0;
83	}

