 32	static bool scaled_rect(const ui_widget_canvas *canvas, ui_rect logical,
 33	                        ui_rect *out_pixels)
 34	{
 35	    if (canvas == NULL || out_pixels == NULL || logical.width == 0U || logical.height == 0U)
 36	        return false;
 37	    double scale = (double)canvas->backing_scale * canvas->ui_scale;
 38	    double raw_x = round((double)logical.x * scale);
 39	    double raw_y = round((double)logical.y * scale);
 40	    double raw_width = round((double)logical.width * scale);
 41	    double raw_height = round((double)logical.height * scale);
 42	    if (!isfinite(raw_x) || !isfinite(raw_y) || !isfinite(raw_width) ||
 43	        !isfinite(raw_height) || raw_x < 0.0 || raw_y < 0.0 ||
 44	        raw_width < 1.0 || raw_height < 1.0 || raw_x > UINT32_MAX ||
 45	        raw_y > UINT32_MAX || raw_width > UINT32_MAX || raw_height > UINT32_MAX)
 46	        return false;
 47	    uint64_t x = (uint64_t)raw_x, y = (uint64_t)raw_y;
 48	    uint64_t width = (uint64_t)raw_width, height = (uint64_t)raw_height;
 49	    if (x > UINT32_MAX || y > UINT32_MAX || width > UINT32_MAX || height > UINT32_MAX ||
 50	        x + width > UINT32_MAX || y + height > UINT32_MAX) return false;
 51	    *out_pixels = (ui_rect){(uint32_t)x, (uint32_t)y, (uint32_t)width, (uint32_t)height};
 52	    return true;
 53	}
 54	
 55	static void blend_pixel(uint8_t *destination, uint32_t color, uint8_t coverage)
 56	{
 57	    uint32_t alpha = (((color & 255U) * (uint32_t)coverage) + 127U) / 255U;
 58	    uint32_t inverse = 255U - alpha;
 59	    uint32_t old_alpha = destination[3];
 60	    uint32_t out_alpha = alpha + (old_alpha * inverse + 127U) / 255U;
 61	    if (out_alpha == 0U) return;
 62	    for (size_t channel = 0U; channel < 3U; ++channel) {
 63	        uint32_t source = (color >> (24U - (uint32_t)(channel * 8U))) & 255U;
 64	        uint32_t numerator = source * alpha * 255U +
 65	            (uint32_t)destination[channel] * old_alpha * inverse;
 66	        destination[channel] = (uint8_t)((numerator + out_alpha * 127U) /
 67	            (out_alpha * 255U));
 68	    }
 69	    destination[3] = (uint8_t)out_alpha;
 70	}
