136	        rect.y >= canvas->height) return;
137	    uint32_t right = rect.x + rect.width, bottom = rect.y + rect.height;
138	    if (right < rect.x || right > canvas->width) right = canvas->width;
139	    if (bottom < rect.y || bottom > canvas->height) bottom = canvas->height;
140	    for (uint32_t y = rect.y; y < bottom; ++y)
141	        for (uint32_t x = rect.x; x < right; ++x)
142	            blend_pixel(canvas->rgba + (size_t)y * canvas->stride + (size_t)x * 4U,
143	                color, 255U);
144	}
