199	    if (!scaled_rect(canvas, bounds, &pixels)) return false;
200	    double text_scale = (double)canvas->text_scale_percent / 100.0;
201	    double scaled_font = ceil((double)font_points * canvas->backing_scale *
202	        canvas->ui_scale * text_scale);
203	    if (!isfinite(scaled_font) || scaled_font < 1.0 || scaled_font > 256.0) return false;
204	    uint32_t font_px = (uint32_t)scaled_font;
205	    return canvas->draw_text(canvas->text_context, text, length, pixels,
206	        canvas->theme, font_px, color, family, weight, canvas->rgba,
207	        canvas->width, canvas->height, canvas->stride);
