249	        foreground = canvas->theme == UI_THEME_LIGHT ? UINT32_C(0xffffffff) :
250	            (spec->state == UI_CONTROL_PRESSED ? canvas->tokens.text_primary :
251	                canvas->tokens.window);
252	    }
253	    if (surface != 0U) ui_widget_paint_round(canvas, spec->bounds, 6U, surface, 0U, 0U);
254	    if (icon_only) {
