256	        if (icon_size > spec->bounds.width) icon_size = spec->bounds.width;
257	        if (icon_size > spec->bounds.height) icon_size = spec->bounds.height;
258	        ui_rect icon_bounds = {spec->bounds.x + (spec->bounds.width - icon_size) / 2U,
259	            spec->bounds.y + (spec->bounds.height - icon_size) / 2U, icon_size, icon_size};
260	        if (spec->icon == UI_ICON_CLOSE && spec->state == UI_CONTROL_REST)
261	            return ui_widget_paint_icon_color(canvas, spec->icon, icon_bounds,
262	                canvas->tokens.text_secondary);
263	        return ui_widget_paint_icon(canvas, spec->icon, icon_bounds, spec->state);
264	    }
265	    if (spec->icon != UI_ICON_NONE) {
266	        ui_rect icon_bounds = {spec->bounds.x + 8U, spec->bounds.y +
267	            (spec->bounds.height > 16U ? (spec->bounds.height - 16U) / 2U : 0U), 16U, 16U};
268	        if (!ui_widget_paint_icon(canvas, spec->icon, icon_bounds, spec->state)) return false;
