   583	bool ui_widget_slider_init(ui_widget_slider *slider, const char *semantic_label,
   584	    size_t label_length, double value, double minimum, double maximum, double step)
   585	{
   586	    if (slider == NULL || !finite_in_range(value, minimum, maximum) ||
   587	        !isfinite(step) || step <= 0.0) return false;
   588	    ui_widget_slider fresh = {0};
   589	    if (!copy_label(fresh.semantic_label, sizeof(fresh.semantic_label), semantic_label,
   590	            label_length, true)) return false;
   591	    fresh.semantic_label_length = label_length; fresh.value = value;
   592	    fresh.minimum = minimum; fresh.maximum = maximum; fresh.step = step;
   593	    *slider = fresh;
   594	    return true;
   595	}
   596	
   597	ui_widget_input_result ui_widget_slider_key(ui_widget_slider *slider,
   598	    uint32_t key, uint32_t modifiers)
   599	{
   600	    if (slider == NULL) return UI_WIDGET_INPUT_INVALID;
   601	    if (key != UI_KEY_UP && key != UI_KEY_DOWN && key != UI_KEY_LEFT && key != UI_KEY_RIGHT)
   602	        return UI_WIDGET_INPUT_UNHANDLED;
   603	    double direction = key == UI_KEY_UP || key == UI_KEY_RIGHT ? 1.0 : -1.0;
   604	    double factor = (modifiers & UI_MOD_SHIFT) != 0U ? 10.0 :
   605	        (modifiers & UI_MOD_OPTION) != 0U ? 0.1 : 1.0;
   606	    double value = slider->value + direction * slider->step * factor;
   607	    if (value < slider->minimum) value = slider->minimum;
   608	    if (value > slider->maximum) value = slider->maximum;
   609	    slider->value = value;
   610	    return UI_WIDGET_INPUT_CHANGED;
   611	}
   612	
   613	static double slider_at(int32_t x, int32_t track_x, uint32_t track_width,
   614	                        double minimum, double maximum, double step)
   615	{
   616	    double position = (double)x - (double)track_x;
   617	    if (position < 0.0) position = 0.0;
   618	    if (position > (double)track_width) position = (double)track_width;
   619	    double ratio = track_width == 0U ? 0.0 : position / (double)track_width;
   620	    double value = minimum + ratio * (maximum - minimum);
   621	    if (step > 0.0) value = minimum + round((value - minimum) / step) * step;
   622	    if (value < minimum) value = minimum;
   623	    if (value > maximum) value = maximum;
   624	    return value;
   625	}
   626	
   627	bool ui_widget_slider_pointer(ui_widget_slider *slider, ui_widget_pointer_event event,
   628	    int32_t x, int32_t track_x, uint32_t track_width)
   629	{
   630	    if (slider == NULL || event > UI_WIDGET_POINTER_CANCEL || track_width == 0U) return false;
   631	    if (event == UI_WIDGET_POINTER_DOWN) slider->dragging = true;
   632	    if ((event == UI_WIDGET_POINTER_UP_INSIDE || event == UI_WIDGET_POINTER_UP_OUTSIDE ||
   633	            event == UI_WIDGET_POINTER_CANCEL) && !slider->dragging) return false;
   634	    if (event == UI_WIDGET_POINTER_ENTER || event == UI_WIDGET_POINTER_LEAVE) return true;
   635	    if (event == UI_WIDGET_POINTER_MOVE && !slider->dragging) return false;
   636	    if (event == UI_WIDGET_POINTER_CANCEL) { slider->dragging = false; return true; }
   637	    slider->value = slider_at(x, track_x, track_width, slider->minimum,
   638	        slider->maximum, slider->step);
   639	    if (event == UI_WIDGET_POINTER_UP_INSIDE || event == UI_WIDGET_POINTER_UP_OUTSIDE)
   640	        slider->dragging = false;
   641	    return true;
   642	}
   643	
   644	bool ui_widget_dropdown_init(ui_widget_dropdown *dropdown,
   645	    const char *semantic_label, size_t label_length,
   646	    const ui_widget_option *options, size_t option_count, size_t selected_index)
   647	{
   648	    if (dropdown == NULL || options == NULL || option_count == 0U ||
   649	        option_count > UI_WIDGET_MAX_OPTIONS || selected_index >= option_count) return false;
   650	    ui_widget_dropdown fresh = {0};
   651	    if (!copy_label(fresh.semantic_label, sizeof(fresh.semantic_label), semantic_label,
   652	            label_length, true)) return false;
   653	    for (size_t index = 0U; index < option_count; ++index) {
   654	        if (!copy_label(fresh.options[index], sizeof(fresh.options[index]),
   655	                options[index].text, options[index].length, true)) return false;
   656	        fresh.option_lengths[index] = (uint8_t)options[index].length;
   657	    }
   658	    fresh.semantic_label_length = label_length;
   659	    fresh.option_count = option_count; fresh.selected_index = selected_index;
   660	    fresh.active_index = selected_index;
   661	    *dropdown = fresh;
   662	    return true;
   663	}
   664	
   665	ui_widget_input_result ui_widget_dropdown_key(ui_widget_dropdown *dropdown,
   666	    uint32_t key, uint32_t modifiers)
   667	{
   668	    (void)modifiers;
   669	    if (dropdown == NULL || dropdown->option_count == 0U) return UI_WIDGET_INPUT_INVALID;
   670	    if (!dropdown->expanded) {
   671	        if (key != UI_KEY_RETURN && key != UI_KEY_SPACE && key != UI_KEY_DOWN &&
   672	            key != UI_KEY_UP) return UI_WIDGET_INPUT_UNHANDLED;
   673	        dropdown->expanded = true;
   674	        dropdown->active_index = dropdown->selected_index;
   675	        return UI_WIDGET_INPUT_CHANGED;
   676	    }
   677	    if (key == UI_KEY_ESCAPE) {
   678	        dropdown->expanded = false; dropdown->active_index = dropdown->selected_index;
   679	        return UI_WIDGET_INPUT_CANCELLED;
   680	    }
   681	    if (key == UI_KEY_RETURN || key == UI_KEY_SPACE) {
   682	        dropdown->selected_index = dropdown->active_index;
   683	        dropdown->expanded = false;
   684	        return UI_WIDGET_INPUT_COMMITTED;
   685	    }
   686	    if (key == UI_KEY_UP || key == UI_KEY_LEFT) {
