296	static void draw_check(const ui_widget_canvas *canvas, ui_rect bounds, uint32_t color)
297	{
298	    ui_rect px = {0};
299	    if (!scaled_rect(canvas, bounds, &px)) return;
300	    uint32_t start_x = px.x + px.width / 4U, mid_x = px.x + px.width * 2U / 5U;
301	    uint32_t end_x = px.x + px.width * 3U / 4U;
302	    uint32_t mid_y = px.y + px.height * 3U / 5U, start_y = px.y + px.height / 2U;
303	    uint32_t end_y = px.y + px.height / 4U;
304	    uint32_t steps = end_x - start_x;
305	    for (uint32_t i = 0U; i <= steps; ++i) {
306	        double t = steps == 0U ? 0.0 : (double)i / (double)steps;
307	        double x = (double)start_x + t * (double)(mid_x - start_x);
308	        double y = (double)start_y + t * (double)(mid_y - start_y);
309	        for (int32_t dy = -1; dy <= 1; ++dy) for (int32_t dx = -1; dx <= 1; ++dx) {
310	            int64_t px_x = (int64_t)llround(x) + dx, px_y = (int64_t)llround(y) + dy;
311	            if (px_x >= 0 && px_y >= 0 && (uint64_t)px_x < canvas->width &&
312	                (uint64_t)px_y < canvas->height)
313	                blend_pixel(canvas->rgba + (size_t)px_y * canvas->stride +
314	                    (size_t)px_x * 4U, color, 255U);
315	        }
316	    }
317	    steps = end_x - mid_x;
318	    for (uint32_t i = 0U; i <= steps; ++i) {
319	        double t = steps == 0U ? 0.0 : (double)i / (double)steps;
320	        double x = (double)mid_x + t * (double)(end_x - mid_x);
321	        double y = (double)mid_y + t * (double)((int32_t)end_y - (int32_t)mid_y);
322	        for (int32_t dy = -1; dy <= 1; ++dy) for (int32_t dx = -1; dx <= 1; ++dx) {
323	            int64_t px_x = (int64_t)llround(x) + dx, px_y = (int64_t)llround(y) + dy;
324	            if (px_x >= 0 && px_y >= 0 && (uint64_t)px_x < canvas->width &&
325	                (uint64_t)px_y < canvas->height)
326	                blend_pixel(canvas->rgba + (size_t)px_y * canvas->stride +
327	                    (size_t)px_x * 4U, color, 255U);
328	        }
329	    }
330	}
