332	static void draw_chevron_segment(const ui_widget_canvas *canvas, int32_t x0,
333	    int32_t y0, int32_t x1, int32_t y1, uint32_t thickness, uint32_t color)
334	{
335	    int32_t dx = x1 - x0, dy = y1 - y0;
336	    uint32_t steps = (uint32_t)(abs(dx) > abs(dy) ? abs(dx) : abs(dy));
337	    for (uint32_t i = 0U; i <= steps; ++i) {
338	        double t = steps == 0U ? 0.0 : (double)i / (double)steps;
339	        int32_t x = (int32_t)llround((double)x0 + (double)dx * t);
340	        int32_t y = (int32_t)llround((double)y0 + (double)dy * t);
341	        int32_t radius = (int32_t)(thickness / 2U);
342	        for (int32_t oy = -radius; oy <= radius; ++oy) {
343	            for (int32_t ox = -radius; ox <= radius; ++ox) {
344	                int64_t px = (int64_t)x + ox, py = (int64_t)y + oy;
345	                if (px >= 0 && py >= 0 && (uint64_t)px < canvas->width &&
346	                    (uint64_t)py < canvas->height)
347	                    blend_pixel(canvas->rgba + (size_t)py * canvas->stride +
348	                        (size_t)px * 4U, color, 255U);
349	            }
350	        }
351	    }
352	}
