354	static void draw_chevron(const ui_widget_canvas *canvas, ui_rect bounds,
355	    bool points_up, uint32_t color)
356	{
357	    ui_rect px = {0};
358	    if (!scaled_rect(canvas, bounds, &px)) return;
359	    int32_t middle_x = (int32_t)(px.x + px.width / 2U);
360	    int32_t middle_y = (int32_t)(px.y + px.height / 2U);
361	    int32_t wing = (int32_t)(px.width / 3U);
362	    int32_t rise = (int32_t)(px.height / 4U);
363	    int32_t left_y = points_up ? middle_y + rise : middle_y - rise;
364	    int32_t right_y = left_y;
365	    int32_t tip_y = points_up ? middle_y - rise : middle_y + rise;
366	    uint32_t thickness = (uint32_t)ceil(2.0 * canvas->backing_scale * canvas->ui_scale);
367	    draw_chevron_segment(canvas, middle_x - wing, left_y, middle_x, tip_y,
368	        thickness, color);
369	    draw_chevron_segment(canvas, middle_x, tip_y, middle_x + wing, right_y,
370	        thickness, color);
371	}
