373	static bool draw_checkbox(const ui_widget_canvas *canvas, const ui_widget_draw_spec *spec)
374	{
375	    ui_rect box = {spec->bounds.x + 6U, spec->bounds.y +
376	        (spec->bounds.height > 16U ? (spec->bounds.height - 16U) / 2U : 0U), 16U, 16U};
377	    bool active = spec->checked || spec->state == UI_CONTROL_SELECTED ||
378	        spec->state == UI_CONTROL_PRESSED;
379	    uint32_t fill = active ? canvas->tokens.accent : canvas->tokens.panel;
380	    if (spec->state == UI_CONTROL_DISABLED) fill = canvas->tokens.panel_raised;
381	    ui_widget_paint_round(canvas, box, 3U, fill, active ? 0U : canvas->tokens.control_edge,
382	        active ? 0U : 1U);
