392	static bool draw_segmented(const ui_widget_canvas *canvas, const ui_widget_draw_spec *spec)
393	{
394	    uint32_t count = spec->segment_count < 2U ? 3U : spec->segment_count;
395	    if (count > 8U) count = 8U;
396	    ui_widget_paint_round(canvas, spec->bounds, 6U, canvas->tokens.panel_raised,
397	        canvas->tokens.separator, 1U);
398	    uint32_t segment_width = spec->bounds.width / count;
399	    uint32_t selected = spec->segment_index < count ? spec->segment_index : 0U;
400	    ui_rect active = {spec->bounds.x + segment_width * selected + 1U,
401	        spec->bounds.y + 1U, segment_width > 2U ? segment_width - 2U : segment_width,
402	        spec->bounds.height > 2U ? spec->bounds.height - 2U : spec->bounds.height};
403	    ui_widget_paint_round(canvas, active, 5U, canvas->tokens.panel, 0U, 0U);
404	    for (uint32_t index = 1U; index < count; ++index) {
405	        ui_rect divider = {spec->bounds.x + segment_width * index, spec->bounds.y + 6U,
406	            1U, spec->bounds.height > 12U ? spec->bounds.height - 12U : 1U};
407	        ui_widget_paint_rect(canvas, divider, canvas->tokens.separator);
408	    }
409	    for (uint32_t index = 0U; index < count; ++index) {
410	        const char *label = spec->segment_labels[index];
411	        size_t length = spec->segment_label_lengths[index];
412	        if (label == NULL || length == 0U) continue;
413	        uint32_t left = spec->bounds.x + segment_width * index + 4U;
414	        uint32_t right = spec->bounds.x + segment_width * (index + 1U);
415	        uint32_t label_width = (uint32_t)(length > UINT32_MAX / 7U ?
416	            UINT32_MAX : length * 7U);
417	        uint32_t available = right > left + 4U ? right - left - 4U : 0U;
418	        if (label_width < available) left += (available - label_width) / 2U;
419	        ui_rect label_bounds = {left, spec->bounds.y + 1U,
420	            right > left + 2U ? right - left - 2U : 0U,
421	            spec->bounds.height > 2U ? spec->bounds.height - 2U : 1U};
422	        ui_font_weight weight = index == selected ? UI_FONT_SEMIBOLD : UI_FONT_REGULAR;
423	        if (!ui_widget_paint_text(canvas, label, length, label_bounds,
424	                ui_widget_paint_state_foreground(canvas, spec->state), UI_FONT_SYSTEM, weight, 12U)) return false;
425	    }
426	    if (spec->segment_labels[0] != NULL) return true;
427	    return ui_widget_paint_text(canvas, spec->label, spec->label_length,
428	        inset(spec->bounds, 8U, 0U, 8U, 0U), ui_widget_paint_state_foreground(canvas, spec->state),
429	        UI_FONT_SYSTEM, UI_FONT_REGULAR, UI_POINT_TEXT);
430	}
