432	static bool draw_tab_bar(const ui_widget_canvas *canvas, const ui_widget_draw_spec *spec)
433	{
434	    uint32_t count = 2U;
435	    uint32_t segment_width = spec->bounds.width / count;
436	    uint32_t selected = spec->segment_index < count ? spec->segment_index : 0U;
437	    const char *label = selected == 0U ? spec->label : spec->secondary;
438	    size_t length = selected == 0U ? spec->label_length : spec->secondary_length;
439	    ui_rect tab = {spec->bounds.x + selected * segment_width, spec->bounds.y,
440	        segment_width, spec->bounds.height};
441	    ui_rect underline = {tab.x + 8U, tab.y + tab.height - 2U,
442	        tab.width > 16U ? tab.width - 16U : tab.width, 2U};
443	    ui_widget_paint_rect(canvas, underline, canvas->tokens.accent);
444	    return ui_widget_paint_text(canvas, label, length, tab, ui_widget_paint_state_foreground(canvas, spec->state),
445	        UI_FONT_SYSTEM, selected == spec->segment_index ? UI_FONT_SEMIBOLD : UI_FONT_REGULAR,
446	        UI_POINT_TEXT);
447	}
