449	static void draw_shadow(const ui_widget_canvas *canvas, ui_rect bounds)
450	{
451	    uint32_t shadow = canvas->tokens.popover_shadow;
452	    static const uint8_t weights[] = {45U, 70U, 90U};
453	    for (size_t layer = 0U; layer < sizeof(weights); ++layer) {
454	        ui_rect spread = {bounds.x, bounds.y + (uint32_t)layer + 1U,
455	            bounds.width, bounds.height};
456	        uint32_t color = (shadow & UINT32_C(0xffffff00)) |
457	            (((shadow & 255U) * weights[layer]) / 255U);
458	        ui_widget_paint_round(canvas, spread, 6U + (uint32_t)layer, color, 0U, 0U);
459	    }
460	}
